# Nxeon primary domain — nxeon.cloud (added during the revsports.ca → nxeon.cloud migration).
# Additive to the generated `nxeon` vhost so the cutover is reversible. The admin
# ops portal stays on its existing secret subdomain until its DNS is moved.

# HTTP -> HTTPS (ACME challenge still served)
server {
    listen 80;
    listen [::]:80;
    server_name nxeon.cloud www.nxeon.cloud;
    location /.well-known/acme-challenge/ { root /var/www/certbot; }
    location / { return 301 https://$host$request_uri; }
}

# Customer portal — https://nxeon.cloud
server {
    listen 443 ssl;
    listen [::]:443 ssl;
    http2 on;
    server_name nxeon.cloud www.nxeon.cloud;
    ssl_certificate /etc/letsencrypt/live/nxeon.cloud/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/nxeon.cloud/privkey.pem;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_ciphers HIGH:!aNULL:!MD5;
    client_max_body_size 20m;
    error_page 502 503 504 /maintenance.html;
    location = /maintenance.html {
        root /opt/nxeon/public;
        internal;
    }
    location /admin { return 404; }
    location ~ ^/(login|register|forgot-password|reset-password)$ {
        limit_req zone=nxeon_auth burst=15 nodelay;
        proxy_pass http://127.0.0.1:3000;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
    }
    location /console-ws {
        proxy_pass http://127.0.0.1:8899/console;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_set_header Host $host;
        proxy_read_timeout 3600s;
    }
    location /terminal-ws {
        proxy_pass http://127.0.0.1:8901;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection $connection_upgrade;
        proxy_set_header Host $host;
        proxy_read_timeout 3600s;
        proxy_send_timeout 3600s;
        proxy_buffering off;
    }
    location / {
        proxy_pass http://127.0.0.1:3000;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
    }
}

