"use server";

import { requireArea } from "./rbac";
import { backfillClaudeCli, backfillClaudeCliAll, type BackfillResult } from "./claude-backfill";

/**
 * Admin (fleet) actions for task #73 — installing Claude Code onto servers that
 * predate the cloud-init bake-in. Every export re-checks requireArea("fleet")
 * inside the function, so a dropped guard can never silently expose it. These
 * SSH into live customer boxes, so they are deliberately admin-only and run one
 * server at a time.
 */

/** Backfill Claude Code onto ONE server (run this on movieshack first). */
export async function backfillServerClaude(serverId: string): Promise<{ error?: string; result?: BackfillResult }> {
  await requireArea("fleet");
  try {
    const result = await backfillClaudeCli(serverId);
    return { result };
  } catch (e) {
    return { error: (e instanceof Error ? e.message : String(e)).slice(0, 300) };
  }
}

/** Backfill every RUNNING server that doesn't yet have it (capped per pass). */
export async function backfillAllServersClaude(
  limit = 25,
): Promise<{ error?: string; results?: { serverId: string; name: string; result: BackfillResult }[] }> {
  await requireArea("fleet");
  try {
    const results = await backfillClaudeCliAll(limit);
    return { results };
  } catch (e) {
    return { error: (e instanceof Error ? e.message : String(e)).slice(0, 300) };
  }
}

