// Task #73 — backfill Claude Code onto EXISTING servers.
//
// New servers get Claude Code baked in via cloud-init (worker/index.ts). Servers
// provisioned before that existed never got it. This runs the SAME install steps
// (lib/claude-install.ts) over SSH on a live server, then verifies the binary is
// actually present — so the result is the honest outcome, never an assumption.
//
// Plain server-side module (no "use server"): callable from a server action or
// the worker. Every caller must have already authorized the operation.

import { db } from "./db";
import { withServerSsh, exec, INSTALL_TIMEOUT_MS, QUICK_TIMEOUT_MS } from "./ssh-exec";
import type { SftpServer } from "./sftp";
import { claudeInstallScript, CLAUDE_PRESENT_PROBE } from "./claude-install";

export type BackfillResult = { ok: boolean; alreadyInstalled: boolean; detail: string };

/** The DB fields connectionTarget()/serverRootPassword() need over SSH, plus
 *  status so we only touch a server that is actually up. */
const SSH_SELECT = {
  id: true,
  status: true,
  rootPassword: true,
  rootPasswordEnc: true,
  sshPort: true,
  dedicatedIp: { select: { address: true } },
} as const;

/**
 * Install (or confirm) Claude Code on one existing server over SSH.
 * Idempotent: if `claude` is already present it reports so without reinstalling.
 */
export async function backfillClaudeCli(serverId: string): Promise<BackfillResult> {
  const server = await db.server.findUnique({ where: { id: serverId }, select: SSH_SELECT });
  if (!server) return { ok: false, alreadyInstalled: false, detail: "Server not found." };
  if (server.status !== "RUNNING") {
    return { ok: false, alreadyInstalled: false, detail: `Server is ${server.status}; skip until it's RUNNING.` };
  }

  return withServerSsh(server as unknown as SftpServer, async (conn) => {
    // Already there? Then this is a no-op success — don't churn the box.
    const pre = await exec(conn, CLAUDE_PRESENT_PROBE, QUICK_TIMEOUT_MS);
    if (pre.stdout.trim() === "yes") {
      return { ok: true, alreadyInstalled: true, detail: "Claude Code was already installed." };
    }

    // Run the shared install script. It internally falls back native -> npm and
    // records /root/.nxeon-claude-installed, but we trust only our own re-probe.
    const script = claudeInstallScript();
    await exec(conn, `cat > /root/nxeon-claude-install.sh <<'NXEON_EOF'\n${script}\nNXEON_EOF`, QUICK_TIMEOUT_MS);
    await exec(conn, "chmod +x /root/nxeon-claude-install.sh", QUICK_TIMEOUT_MS);
    const run = await exec(conn, "bash /root/nxeon-claude-install.sh > /var/log/nxeon-claude-install.log 2>&1; echo done", INSTALL_TIMEOUT_MS);

    // The ONLY thing that decides success is whether the binary now runs.
    const post = await exec(conn, CLAUDE_PRESENT_PROBE, QUICK_TIMEOUT_MS);
    if (post.stdout.trim() === "yes") {
      return { ok: true, alreadyInstalled: false, detail: "Claude Code installed." };
    }
    const tail = (await exec(conn, "tail -n 12 /var/log/nxeon-claude-install.log 2>/dev/null || true", QUICK_TIMEOUT_MS)).stdout.trim();
    return {
      ok: false,
      alreadyInstalled: false,
      detail: `Install ran but 'claude' is still not on PATH. Last log lines:\n${tail || run.stdout.trim()}`.slice(0, 800),
    };
  });
}

